mapper.select:
SELECT 
FROM CALLMSTR c 
WHERE 
AND c.CALL_DATE >= #{from}
AND c.CALL_DATE <= #{to}
AND c.ORG_MSTR_CODE = #{region}
AND c.ORG_CODE = #{district}
ORDER BY c.CALL_DATE DESC, c.CALL_TIME DESC, c.CALL_ID ASC
LIMIT #{limit}

mapper.update:
UPDATE CALLMSTR c SET
c.TGT_ID = #{personId}, c.TGT_NAME_HAN = #{personName}, c.TGT_CODE = #{personCode}, c.INTRO_NAME = #{introducer}, c.ORG_MSTR_CODE = #{regionCode}, c.ORG_CODE = #{districtCode}, c.BAN_CODE = #{className}, c.FOUND_DATE = #{foundDate},
c.CALL_DATE = #{date}, c.CALL_TIME = #{time}, c.CALLER_NAME = #{caller}, c.ROUND_NO = #{roundNo}, c.ROUND_NAME = #{roundName}, c.RESULT_CODE = #{result}, c.ORIGINAL_RESULT = #{originalResult}, c.REPORTED_RESULT = #{reportedResult}, c.NOTES = #{notes}, c.ATTEMPT_KEY_HASH = #{attemptHash}, c.SYS_MUSR_ID = #{sysUserId}, c.SYS_MUSR_IP = #{sysIp}, c.SYS_MUSR_DTTM = #{sysAt} WHERE AND c.CALL_ID = CAST(#{id} AS UNSIGNED) AND () = #{expectedVersion}

mapper.delete:
DELETE c FROM CALLMSTR c
WHERE  AND c.CALL_ID = CAST(#{id} AS UNSIGNED)
  AND () = #{expectedVersion}
